def mdtable(headers,rows):return '\n'.join(['|'+'|'.join(headers)+'|','|'+'|'.join(['---']*len(headers))+'|']+['|'+'|'.join(str(v) for v in row)+'|' for row in rows])+'\n'
def fmt(v):return f'{float(v):.2f}' if v not in [None,''] else 'unknown'
cases=read('Chronological_Cases.json.gz');validation=read('Chronological_Validation.csv');cal=read('Probability_Calibration.csv');league=read('League_1900_Comparison.csv');named=[a for a in read('Diagnostic_12_Comparisons.csv') if a['candidate']=='fitted'];summary=read('Population_Component_Attribution.csv');gates=read('Release_Gates.json');coverage=read('Training_Coverage.json')
