        groups=list(by.values());sums=np.array([sum(g) for g in groups]);sizes=np.array([len(g) for g in groups]);rng=np.random.default_rng(2718);ix=rng.integers(0,len(groups),(1500,len(groups)));ci=np.quantile(sums[ix].sum(1)/sizes[ix].sum(1),[.025,.975]);paired.append({'family':fam,'method':method,'player_clusters':len(groups),'delta_MAE_vs_frozen':float(sums.sum()/sizes.sum()),'paired95_low':float(ci[0]),'paired95_high':float(ci[1]),'status':'descriptive exposed evidence; not independent confirmation'})
